function esc(s=''){return s.replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
const INTRO_RUBRIC=[
{level:6,points:12,label:'Exceptional / College-Level',desc:'Complete TAG; precise audience and exigence; specific rhetorical choices; sophisticated, nuanced purpose; mature vocabulary and professional control.'},
{level:5,points:10,label:'Strong',desc:'Accurate TAG, audience, exigence, specific rhetorical choices, and clear purpose; polished and analytical, with slightly less nuance or precision than a 6.'},
{level:4,points:8,label:'Proficient',desc:'Includes the major required elements accurately; purpose and rhetorical situation are clear, though one element may be broad or underdeveloped.'},
{level:3,points:6,label:'Developing',desc:'Generally correct understanding, but one or more elements are vague, partial, or insufficiently connected; analysis lacks precision or depth.'},
{level:2,points:4,label:'Limited',desc:'Partial understanding; several required elements are missing, broad, or weakly connected; purpose may be reduced to a simple action.'},
{level:1,points:2,label:'Minimal',desc:'Very limited understanding; mostly summary, generic device language, incomplete rhetorical situation, or a vague purpose.'},
{level:0,points:0,label:'No Credit',desc:'Blank, off-topic, copied from the prompt without meaningful original analysis, or no genuine attempt.'}
];
const SKILL_GROUPS=[
{name:'Rhetorical Situation & Purpose',ids:[1,2,10,11,20]},
{name:'Tone & Tone Shift',ids:[3,13]},
{name:'Diction',ids:[4,9,12]},
{name:'Syntax',ids:[5,6,7,8,14,15,16,19]},
{name:'Rhetorical Devices & Effect',ids:[17,18]}
];
function introRubricHtml(){return `<details class="rubric-details"><summary>View the 1–6 Introduction Rubric</summary><div class="rubric-table">${INTRO_RUBRIC.filter(r=>r.level>0).map(r=>`<div class="rubric-row"><div><b>${r.level}</b><span>${r.points} pts</span></div><p><strong>${r.label}.</strong> ${r.desc}</p></div>`).join('')}</div></details>`;}
function gradeIntroduction(text){
  const raw=(text||'').trim();
  if(!raw)return{level:0,points:0,label:'No Credit',summary:'No introduction was submitted.'};
  const t=raw.toLowerCase().replace(/[“”]/g,'"').replace(/[’]/g,"'");
  const words=(raw.match(/[A-Za-z][A-Za-z’'\-]*/g)||[]);
  const wc=words.length;
  const sentences=(raw.match(/[.!?]+(?=\s|$)/g)||[]).length;

  const title=/measure of prosperity/.test(t);
  const author=/clara avery|\bavery\b/.test(t);
  const genre=/\b(speech|address|remarks)\b/.test(t);
  const tagCount=[title,author,genre].filter(Boolean).length;

  const namedAudience=/\b(industrial community|community members?|citizens?|residents?|business leaders?|civic leaders?|city leaders?|workers?|factory owners?|industrial leaders?|people of the city|members of (?:the|her) community|employers?|families|people who sustain|those who sustain)\b/.test(t);
  const audienceFrame=/\b(address(?:es|ed|ing)|speaks? to|appeals? to|urges?|persuades?|challenges?)\b.{0,100}\b(?:community|citizens?|residents?|leaders?|workers?|owners?|families|audience|people)\b/.test(t);
  const audience=namedAudience||audienceFrame;

  const topicContext=/\b(industrial(?:ization| growth| expansion| prosperity)|rapid growth|economic growth|prosperity|working conditions?|worker security|economic security|unequal distribution|inequality|wages?|factories|industry|labor conditions?|quality of life|benefits? of growth|distribution of wealth|conditions of labor|workers' lives|workers lives|industrial success)\b/.test(t);
  const contextFrame=/\b(amid|during|while|as|because|following|in response to|against the backdrop of|at a time when)\b.{0,170}\b(industry|industrial|prosperity|growth|workers?|labor|security|conditions?|wealth|production|factories|families)\b/.test(t);
  const exigence=topicContext||contextFrame;
  const preciseEx=contextFrame||(/\b(amid|during|while|as|because|following|in response to|against the backdrop of|at a time when)\b/.test(t)&&topicContext);

  const devicePatterns={
    'anaphora':/\banaphora\b/,
    'polysyndeton':/\bpolysyndeton\b/,
    'loose\/cumulative syntax':/\bloose(?:\/cumulative)?\b|\bcumulative\b/,
    'antithesis':/\bantithesis\b/,
    'parallelism':/\bparallel\w*\b/,
    'diction':/\bdiction\b|sensory language|laudatory language|loaded language|sensory diction|laudatory diction|loaded diction/,
    'tone':/\btone\b/,
    'syntax':/\bsyntax\b/,
    'repetition':/\brepetition\b/,
    'imagery':/\bimagery\b|\bimage\b/
  };
  const devices=Object.entries(devicePatterns).filter(([_,rx])=>rx.test(t)).map(([name])=>name);
  const genericDevice=/rhetorical devices?|rhetorical choices?/.test(t)&&devices.length===0;
  const effect=/\b(emphasiz\w*|challeng\w*|highlight\w*|reveal\w*|accumulat\w*|force\w*|prompt\w*|reinforc\w*|underscore\w*|illustrat\w*|convey\w*|stress\w*|connect\w*|complicat\w*|redefin\w*|broaden\w*|contrast\w*|establish\w*)\b/.test(t);

  const purposeVerb=/\b(persuad\w*|urg\w*|encourag\w*|challeng\w*|convinc\w*|advocat\w*|call\w*|motivat\w*|prompt\w*|redefin\w*|broaden\w*|emphasiz\w*|argu\w*)\b/.test(t);
  const purposeTopic=/\b(judge prosperity|measure prosperity|define prosperity|redefine prosperity|broaden.{0,25}prosperity|worker(?:s|'s)? (?:security|well-being|welfare|quality of life)|economic security|quality of life|human well-being|conditions of workers|conditions of labor|benefits? of (?:industry|growth|prosperity)|prosperity.{0,55}(?:workers|families|security|quality of life|well-being)|industrial growth.{0,55}(?:workers|families|security|well-being)|production.{0,50}(?:security|life|workers)|people who sustain|those who sustain|human cost|shared prosperity|common life|prosperity should benefit)\b/.test(t);
  const purposeFrame=/\b(to|so that|in order to|ultimately)\b.{0,160}\b(prosperity|workers?|families|security|well-being|quality of life|industrial growth|economic growth|common life|community)\b/.test(t);
  const purposePresent=purposeVerb||purposeTopic||purposeFrame;
  const purposeStrong=purposeVerb&&(purposeTopic||purposeFrame);
  const nuance=(purposeTopic||purposeFrame)&&/\b(not only|not merely|rather than|while|without|also|both|beyond|as well as|more than|alongside|although|even as)\b/.test(t);
  const audiencePurposeLink=audience&&(purposeTopic||purposeFrame);

  const mechanicsOK=sentences>=2 && /^[A-Z“\"'‘]/.test(raw) && /[.!?]$/.test(raw);
  const relevant=title||author||topicContext||purposeTopic||purposeFrame;
  if(!relevant || wc<15)return{level:0,points:0,label:'No Credit',summary:'The response does not provide enough relevant rhetorical-analysis writing to score.'};

  const basic=[tagCount>=2,audience,exigence,devices.length>=1,purposePresent];
  const basicCount=basic.filter(Boolean).length;
  let level=1;
  if(wc>=18 && basicCount>=2) level=2;
  if(wc>=22 && basicCount>=3) level=3;

  // A competent complete introduction belongs at 4 or above; narrow keyword matching cannot trap it at a 3.
  if(wc>=25 && tagCount>=2 && (audience||exigence) && devices.length>=1 && purposePresent && mechanicsOK) level=Math.max(level,4);

  // A solid AP-style introduction earns a 5 when it contains TAG, rhetorical situation, two specific choices, and a clear purpose.
  const strongCore=tagCount>=2 && audience && exigence && devices.length>=2 && purposePresent && mechanicsOK;
  const strongFallback=tagCount===3 && devices.length>=2 && purposeStrong && (audience||exigence) && mechanicsOK;
  if(wc>=30 && (strongCore||strongFallback)) level=Math.max(level,5);

  // A 6 is reserved for the same completeness plus unusually precise situation, rhetorical function, and nuanced purpose.
  if(wc>=45 && tagCount===3 && audience && preciseEx && devices.length>=2 && purposeStrong && mechanicsOK && effect && nuance && audiencePurposeLink) level=6;

  // Missing elements cap scores proportionally instead of collapsing otherwise strong work to a 2.
  if(!audience && !exigence) level=Math.min(level,3);
  else if(!audience || !exigence) level=Math.min(level,4);
  if(devices.length===0) level=Math.min(level,4);
  if(!purposePresent) level=Math.min(level,3);
  if(genericDevice && devices.length===0) level=Math.min(level,4);
  if(wc<18)level=Math.min(level,1);

  const row=INTRO_RUBRIC.find(r=>r.level===level);
  const strengths=[];
  if(tagCount===3)strengths.push('complete T.A.G.'); else if(tagCount>=2)strengths.push('T.A.G. mostly present');
  if(audience&&exigence)strengths.push(preciseEx?'audience + precise exigence':'audience + exigence');
  else if(audience||exigence)strengths.push('partial rhetorical situation');
  if(devices.length>=2)strengths.push(`${devices.slice(0,2).join(' + ')}`); else if(devices.length===1)strengths.push(devices[0]);
  if(effect)strengths.push('device function');
  if(purposeStrong)strengths.push(nuance?'nuanced purpose':'clear purpose'); else if(purposePresent)strengths.push('general purpose');
  if(mechanicsOK)strengths.push('professional sentence control');
  return{level,points:level*2,label:row.label,summary:strengths.length?`Detected: ${strengths.join(' • ')}.`:'Response shows a limited but relevant attempt.',wordCount:wc};
}
function skillStats(){return SKILL_GROUPS.map(g=>{const arr=g.ids.map(id=>questions[id-1]);const correct=arr.filter(q=>state.originalAnswers[q.id]===q.answer).length;return{name:g.name,correct,total:arr.length,pct:Math.round(correct/arr.length*100)};});}
function scoreSummary(){const mc=state.firstScore??questions.filter(q=>state.originalAnswers[q.id]===q.answer).length;const intro=state.introGrade||gradeIntroduction(state.intro);const recovered=Object.keys(state.halfCreditRecovered||{}).filter(id=>state.halfCreditRecovered[id]).length;const fullCredit=Number((mc*4.4).toFixed(1));const recoveryPoints=Number((recovered*2.2).toFixed(1));const mcPoints=Number((fullCredit+recoveryPoints).toFixed(1));const overall=Number((mcPoints+intro.points).toFixed(1));return{mc,intro,recovered,fullCredit,recoveryPoints,mcPoints,overall};}
function shell(inner,status=''){app.innerHTML=`<div class="shell"><div class="topbar"><div class="brand"><b>AP Language</b> // Rhetorical Analysis Practice Exam</div><div class="status">${status}</div></div><div class="card">${inner}</div></div>`}
function questionPromptHtml(q){return `<div class="stem">${esc(q.stem)}</div>${q.excerpt?`<div class="question-excerpt">${esc(q.excerpt)}</div>`:''}`;}
function render(){if(state.screen==='entry')return entry();if(state.screen.startsWith('read'))return reading(+state.screen.slice(4));if(state.screen==='intro')return intro();if(state.screen==='question')return question();if(state.screen==='submit')return submit();if(state.screen==='corrections')return corrections();if(state.screen==='report')return report();}
function entry(){const resumable=state.student.first&&state.screen!=='entry';shell(`<div class="hero"><div class="entry"><div class="eyebrow">Timed Practice // Two-Passage Sister Exam</div><h1>Rhetorical<br>Analysis Practice</h1><p>Two passages matched to the exam’s length and rigor. Twenty AP-style questions. One rhetorical-analysis introduction. Your progress is saved automatically on this browser.</p><div class="formula-box"><div class="eyebrow">Skills Assessed</div><div style="margin-top:8px"><span class="badge">Rhetorical Situation</span><span class="badge">Author's Purpose</span><span class="badge">Tone</span><span class="badge">Diction</span><span class="badge">Syntax</span></div></div>${resumable?`<div class="resume"><b>Practice in progress:</b> ${esc(state.student.first)} ${esc(state.student.last)} — Period ${esc(state.student.period)}<div style="margin-top:10px"><button class="btn gold" onclick="resumeExam()">Resume Practice</button> <button class="btn secondary" onclick="resetExam()">Start New</button></div></div>`:`<div class="grid2"><div class="field"><label>First Name</label><input id="first" autocomplete="off"></div><div class="field"><label>Last Name</label><input id="last" autocomplete="off"></div></div><div class="field"><label>Class Period</label><select id="period"><option value="">Choose period</option>${[1,2,3,4,5,6,7].map(n=>`<option>${n}</option>`).join('')}</select></div><button class="btn" onclick="startExam()">Begin Practice Exam</button>`}</div></div>`,'Progress autosaves');}
function startExam(){const first=document.getElementById('first').value.trim(),last=document.getElementById('last').value.trim(),period=document.getElementById('period').value;if(!first||!last||!period)return alert('Enter first name, last name, and class period.');state=blankState();state.student={first,last,period};state.screen='read1';save();render();}
function resumeExam(){renderScreenFromState();}
function renderScreenFromState(){render();}
function resetExam(){if(confirm('Start a new assessment? This will erase saved progress on this browser.')){localStorage.removeItem(STORAGE);state=blankState();render();}}
let tickHandle=null;
function setTimer(end,elId,mode){clearInterval(tickHandle);function tick(){const el=document.getElementById(elId);if(!el)return clearInterval(tickHandle);const ms=end-Date.now();if(ms<=0){el.textContent=mode==='q'?'TIME EXPIRED — ANSWER STILL ACCEPTED':'00:00';el.classList.add('expired');if(mode==='read')document.getElementById('readNext').textContent='Begin Questions';return;}const sec=Math.ceil(ms/1000),m=Math.floor(sec/60),s=sec%60;el.textContent=`${m}:${String(s).padStart(2,'0')}`;}tick();tickHandle=setInterval(tick,500)}
function reading(p){if(!state.readingStarted[p]){state.readingStarted[p]=Date.now();state.readingEnds[p]=Date.now()+7*60*1000;save()}const ps=passages[p];shell(`<div class="exam-head"><div><div class="phase">Passage ${p} // Reading</div><b>${esc(ps.title)}</b></div><div id="timer" class="timer"></div></div><div class="reading-wrap"><div class="passage-pane"><h2>${esc(ps.title)}</h2><div class="byline">${esc(ps.by)}</div>${ps.html}</div><div class="side-pane"><div><div class="eyebrow">Reading Window</div><h3>Read and annotate mentally.</h3><p class="instructions">You have <b>7 minutes</b> to read. You may move on early when you are finished. The passage will remain visible during every question.</p><p class="mini">Closing the browser will not erase your progress. The timer will not restart when you return.</p></div><button id="readNext" class="btn gold" onclick="finishReading(${p})">Finished Reading — Begin Questions</button></div></div>`,`${esc(state.student.first)} ${esc(state.student.last)} • Period ${esc(state.student.period)}`);setTimer(state.readingEnds[p],'timer','read');}
function finishReading(p){state.currentQ=p===1?1:11;state.screen='question';save();render();}
function question(){const q=questions[state.currentQ-1],p=q.p,ps=passages[p];if(!state.questionEnds[q.id]){state.questionEnds[q.id]=Date.now()+2*60*1000;save()}const chosen=state.answers[q.id]||'';shell(`<div class="exam-head"><div><div class="phase">Passage ${p} // Question ${p===1?q.id:q.id-10} of 10</div><b>${esc(q.skill)}</b></div><div id="timer" class="timer"></div></div><div class="qwrap"><div class="passage-pane"><h2>${esc(ps.title)}</h2><div class="byline">${esc(ps.by)}</div>${ps.html}</div><div class="qpanel"><div class="qmeta">Question ${q.id} • ${esc(q.skill)}</div>${questionPromptHtml(q)}${q.choices.map((c,i)=>{const L='ABCD'[i];return`<button class="choice ${chosen===L?'selected':''}" onclick="choose('${L}')"><span class="letter">${L}</span><span>${esc(c)}</span></button>`}).join('')}<div class="navrow"><button class="btn secondary" onclick="backQuestion()" ${q.id===1||q.id===11?'disabled':''}>Previous</button><button class="btn" onclick="nextQuestion()" ${!chosen?'disabled':''}>${q.id===10?'Write Introduction':q.id===20?'Review & Submit':'Next Question'}</button></div><p class="mini">If the timer reaches zero, you may still answer with no penalty.</p></div></div>`,`${esc(state.student.first)} ${esc(state.student.last)} • Period ${esc(state.student.period)}`);setTimer(state.questionEnds[q.id],'timer','q');}
function choose(L){state.answers[state.currentQ]=L;save();render();}
function backQuestion(){state.currentQ--;save();render();}
function nextQuestion(){if(!state.answers[state.currentQ])return; if(state.currentQ===10){state.screen='intro'}else if(state.currentQ===20){state.screen='submit'}else state.currentQ++;save();render();}
function intro(){const p=passages[1];shell(`<div class="exam-head"><div><div class="phase">Passage 1 // Writing</div><b>Rhetorical Analysis Introduction</b></div><div class="timer">12 POINTS</div></div><div class="intro"><div class="passage-pane"><h2>${esc(p.title)}</h2><div class="byline">${esc(p.by)}</div>${p.html}</div><div class="intro-panel"><div class="passage-sticky-note">Passage 1 remains visible on the left while you write.</div><div class="formula"><div class="eyebrow">Prompt</div><h3>${esc(p.prompt)}</h3><p class="instructions">Write the introductory paragraph only. The introduction is worth <b>12 points</b> of the 100-point assessment and is scored on a <b>1–6 rubric</b>: 1=2 pts, 2=4 pts, 3=6 pts, 4=8 pts, 5=10 pts, 6=12 pts.</p><div class="formula-box"><b>T.A.G. + RHETORICAL SITUATION</b><br><span class="mini">Title • Author/Speaker • Genre • Intended Audience • Exigence</span></div><div class="formula-box"><b>DEVICES + AUTHOR’S PURPOSE</b><br><span class="mini">Preview specific rhetorical choices you will analyze and state precisely what the speaker hopes to accomplish.</span></div>${introRubricHtml()}<p class="mini rubric-note">The game scores the paragraph against this rubric after final submission. Your exact introduction will also appear on the Final Accuracy Report.</p></div><div class="writing-label"><div class="qmeta">Your Introduction</div><span class="mini">Autosaves as you type</span></div><textarea id="introText" class="intro-box" oninput="saveIntro()" placeholder="Write your introduction here...">${esc(state.intro)}</textarea><div class="navrow"><button class="btn secondary" onclick="state.screen='question';state.currentQ=10;save();render()">Back to Question 10</button><button class="btn" onclick="goPassage2()" ${state.intro.trim().length<40?'disabled':''}>Continue to Passage 2</button></div></div></div>`,`${esc(state.student.first)} ${esc(state.student.last)} • Period ${esc(state.student.period)}`);}
function saveIntro(){state.intro=document.getElementById('introText').value;save();const b=document.querySelector('.navrow .btn:not(.secondary)');if(b)b.disabled=state.intro.trim().length<40;}
function goPassage2(){if(state.intro.trim().length<40)return alert('Complete your introductory paragraph before continuing.');state.screen='read2';save();render();}
function submit(){const missing=questions.filter(q=>!state.answers[q.id]);shell(`<div class="submit-zone"><div class="submit-card"><div class="eyebrow">Practice Checkpoint</div><h2>Ready to Submit Practice?</h2><p class="instructions">Once submitted, your <b>20 multiple-choice answers and introduction are locked for scoring</b>. Each multiple-choice item is worth <b>4.4 points</b> (88 total), and the introduction is worth <b>12 points</b>, for a 100-point assessment. Any missed multiple-choice questions will move into required corrections. A missed multiple-choice question earns <b>half credit (2.2 points)</b> only if it is corrected correctly on the <b>first correction attempt</b>. Later corrections are still required, but do not earn points.</p><div class="formula-box">Multiple Choice: <b>${20-missing.length}/20 answered</b><br>Introduction: <b>${state.intro.trim()?'Saved':'Missing'}</b></div>${missing.length?`<p class="warn">You still have unanswered questions.</p><button class="btn secondary" onclick="goFirstMissing()">Return to Missing Question</button>`:`<button class="btn danger" onclick="finalSubmit()">Submit Practice Exam</button>`}</div></div>`,`${esc(state.student.first)} ${esc(state.student.last)} • Period ${esc(state.student.period)}`);}
function goFirstMissing(){state.currentQ=questions.find(q=>!state.answers[q.id]).id;state.screen='question';save();render();}
function finalSubmit(){state.originalAnswers={...state.answers};state.submitted=true;state.firstScore=questions.filter(q=>state.originalAnswers[q.id]===q.answer).length;state.introGrade=gradeIntroduction(state.intro);state.corrections={};state.correctionAttempts={};state.halfCreditRecovered={};const firstMissed=questions.find(q=>state.originalAnswers[q.id]!==q.answer);state.repairQ=firstMissed?firstMissed.id:null;state.screen=firstMissed?'corrections':'report';save();render();}
function missed(){return questions.filter(q=>state.originalAnswers[q.id]!==q.answer)}
function corrections(){
  const m=missed();
  if(!m.length){state.screen='report';save();return report()}
  const unresolved=m.filter(q=>state.corrections[q.id]!==q.answer);
  const done=m.length-unresolved.length;
  if(!state.repairQ || !m.some(q=>q.id===state.repairQ)) state.repairQ=(unresolved[0]||m[m.length-1]).id;
  const current=questions[state.repairQ-1];
  const position=m.findIndex(q=>q.id===current.id)+1;
  shell(`<div class="correction-head"><div class="eyebrow">Required Corrections // Practice Recovery</div><h2 class="screen-title" style="font-size:2.8rem">Correct Every Missed Question</h2><p class="instructions">Every missed item must be corrected before the Final Practice Report unlocks. <b>Correct a missed question on the first correction attempt to recover half credit (2.2 points).</b> If the first correction is wrong, keep working until the question is correct; later attempts remain required but earn no additional points.</p><p><span class="badge">Required Correction ${position} of ${m.length}</span><span class="badge">Corrected ${done}/${m.length}</span><span class="badge">First-Attempt MC ${state.firstScore}/20</span><span class="badge">Half-Credit Recoveries ${Object.keys(state.halfCreditRecovered||{}).filter(id=>state.halfCreditRecovered[id]).length}</span></p></div><div class="signal-grid">${m.map(q=>{const ok=state.corrections[q.id]===q.answer;const active=q.id===state.repairQ;return`<div class="signal ${ok?'correct':'damaged'} ${active?'active':''}"><div class="wave">∿∿∿∿∿∿∿∿∿∿∿</div><b>Question ${q.id}</b><span class="mini">${ok?'CORRECTED':active?'CORRECTION IN PROGRESS':'CORRECTION REQUIRED'}</span></div>`}).join('')}</div><div class="repair" id="repairZone">${repairHtml(state.repairQ)}</div>`,`${esc(state.student.first)} ${esc(state.student.last)} • Corrections Required`);
}
function repairHtml(id){
  const q=questions[id-1],p=passages[q.p],current=state.corrections[id]||'',correct=current===q.answer,attempts=(state.correctionAttempts||{})[id]||0,half=!!(state.halfCreditRecovered||{})[id];
  return`<div class="repair-split"><div class="passage-pane correction-passage"><h2>${esc(p.title)}</h2><div class="byline">${esc(p.by)}</div>${p.html}</div><div class="repair-box"><div class="qmeta">Required Correction • Question ${id} • ${esc(q.skill)}</div>${questionPromptHtml(q)}${q.choices.map((c,i)=>{const L='ABCD'[i];return`<button class="choice ${current===L?'selected':''}" onclick="repairChoose(${id},'${L}')" ${correct?'disabled':''}><span class="letter">${L}</span><span>${esc(c)}</span></button>`}).join('')}${current?`<div class="feedback ${correct?'good':'bad'}">${correct?(half?'Correct — first correction attempt. <b>Half credit earned: +2.2 points.</b>':'Correct. Correction accepted; no half credit because the first correction attempt was incorrect.'):`Not yet. This was correction attempt ${attempts}. Analytical cue: ${esc(q.hint)}`}</div>`:''}${correct?`<div class="navrow"><span></span><button class="btn gold" onclick="continueCorrections()">${missed().every(x=>state.corrections[x.id]===x.answer)?'Unlock Final Practice Report':'Next Required Correction'}</button></div>`:''}</div></div>`;
}
function repairChoose(id,L){
  if(state.corrections[id]===questions[id-1].answer)return;
  state.correctionAttempts=state.correctionAttempts||{};
  state.halfCreditRecovered=state.halfCreditRecovered||{};
  state.correctionAttempts[id]=(state.correctionAttempts[id]||0)+1;
  state.corrections[id]=L;
  if(L===questions[id-1].answer && state.correctionAttempts[id]===1)state.halfCreditRecovered[id]=true;
  save();corrections();
}
function continueCorrections(){
  const unresolved=missed().filter(q=>state.corrections[q.id]!==q.answer);
  if(unresolved.length){state.repairQ=unresolved[0].id;save();corrections();document.getElementById('repairZone')?.scrollIntoView({behavior:'smooth'});}
  else{state.repairQ=null;state.screen='report';save();report();}
}
function report(){
  if(!state.introGrade)state.introGrade=gradeIntroduction(state.intro);
  const sc=scoreSummary();
  const stats=skillStats();
  const p1=questions.slice(0,10).filter(q=>state.originalAnswers[q.id]===q.answer).length;
  const p2=questions.slice(10).filter(q=>state.originalAnswers[q.id]===q.answer).length;
  shell(`<div class="report"><div class="eyebrow">Final Practice Report // Corrections Complete</div><h2 class="report-name">${esc(state.student.first)} ${esc(state.student.last)} — Period ${esc(state.student.period)}</h2>
  <div class="score-summary">
    <div class="metric primary"><div class="metric-label">Overall Score</div><div class="metric-value">${sc.overall}<span>/100</span></div><div class="metric-note">MC ${sc.mcPoints}/88 + Intro ${sc.intro.points}/12</div></div>
    <div class="metric"><div class="metric-label">Multiple Choice</div><div class="metric-value">${sc.mc}<span>/20</span></div><div class="metric-note">First-attempt correct • ${sc.mcPoints}/88 points after ${sc.recovered} half-credit recoveries</div></div>
    <div class="metric"><div class="metric-label">Introduction</div><div class="metric-value">${sc.intro.level}<span>/6</span></div><div class="metric-note">${sc.intro.points}/12 points • ${esc(sc.intro.label)}</div></div>
  </div>
  <div class="report-grid"><div class="scorecard"><div class="qmeta">Multiple-Choice Data // First Attempt</div><p><span class="badge">Corrections Complete</span><span class="badge">Passage 1 ${p1}/10</span><span class="badge">Passage 2 ${p2}/10</span><span class="badge">Half-Credit Recoveries ${sc.recovered}</span></p><h3>Skill Breakdown</h3>${stats.map(x=>`<div class="skill"><span>${esc(x.name)}</span><b>${x.correct}/${x.total} <small>${x.pct}%</small></b></div>`).join('')}<div class="intro-grade-box"><div class="qmeta">Introduction Rubric</div><div class="intro-level">${sc.intro.level}/6 <span>${sc.intro.points}/12 pts</span></div><p>${esc(sc.intro.summary||'')}</p></div><p class="mini" style="margin-top:18px">Overall score = 4.4 points for each first-attempt correct multiple-choice answer + 2.2 points for each missed item corrected correctly on the first correction attempt + introduction rubric points. Skill data and the /20 count remain based on first-attempt accuracy.</p></div><div class="writing-card"><div class="qmeta" style="color:#675c49">Rhetorical Analysis Introduction</div><h3>Student Response</h3><div class="student-writing">${esc(state.intro)}</div></div></div><div class="footer-actions"><button class="btn" onclick="window.print()">Print / Save Report</button><button class="btn secondary" onclick="copyReport()">Copy Student Summary</button></div></div>`,`${esc(state.student.first)} ${esc(state.student.last)} • Practice Report`);
  save();
}
function copyReport(){const sc=scoreSummary();const stats=skillStats();const skills=stats.map(x=>`${x.name}: ${x.correct}/${x.total} (${x.pct}%)`).join('\n');const txt=`${state.student.first} ${state.student.last} | Period ${state.student.period}\nOVERALL: ${sc.overall}/100\nMultiple Choice first-attempt correct: ${sc.mc}/20\nMultiple Choice points: ${sc.mcPoints}/88 (${sc.recovered} half-credit recoveries = +${sc.recoveryPoints} pts)\nIntroduction: ${sc.intro.level}/6 = ${sc.intro.points}/12 points\nCorrections: Complete\n\nSKILL BREAKDOWN — FIRST ATTEMPT\n${skills}\n\nINTRODUCTION:\n${state.intro}`;navigator.clipboard?.writeText(txt).then(()=>alert('Summary copied.')).catch(()=>alert('Copy unavailable in this browser.'));}
render();
